import { Howl, Howler } from 'howler';
import { BASE_PATH } from '@/lib/paths';
import { $muted, $volume } from '@/model/ui';

// Files are generated by scripts/gen-sounds.mjs. Bump when they change, so browsers drop the cached ones.
const VERSION = 4;
export type Sfx = 'rustle' | 'flutter' | 'clink' | 'crack' | 'till' | 'oink' | 'oinkoink';

/** Mix between sounds; the master volume ($volume) scales all of them. */
const MIX: Record<Sfx, number> = { rustle: 0.7, flutter: 0.6, clink: 0.5, crack: 0.8, till: 0.7, oink: 0.7, oinkoink: 0.75 };
/** The same sound won't retrigger faster than this — a pile of coins shouldn't machine-gun. */
const MIN_GAP_MS = 70;

const howls = new Map<Sfx, Howl>();
const lastPlayed = new Map<Sfx, number>();

function howl(name: Sfx) {
  let h = howls.get(name);
  if (!h) {
    // Public files sit under the base path on GitHub Pages.
    h = new Howl({ src: [`${BASE_PATH}/sounds/${name}.wav?v=${VERSION}`], volume: MIX[name], preload: true });
    howls.set(name, h);
  }
  return h;
}

/** Plays with a slightly random pitch so repeated sounds don't feel mechanical. */
export function play(name: Sfx, delay = 0) {
  if (typeof window === 'undefined' || $muted.getState()) return;
  const fire = () => {
    const now = performance.now();
    if (now - (lastPlayed.get(name) ?? 0) < MIN_GAP_MS) return;
    lastPlayed.set(name, now);
    const h = howl(name);
    const id = h.play();
    h.rate(0.92 + Math.random() * 0.16, id);
  };
  if (delay > 0) setTimeout(fire, delay * 1000);
  else fire();
}

export function preload() {
  (Object.keys(MIX) as Sfx[]).forEach(howl);
}

$muted.watch(m => Howler.mute(m));
$volume.watch(v => Howler.volume(v));
